patch.content:
body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }

h2 {
  font-size: 15px;
  font-family: ui-monospace, "Cascadia Mono", monospace;
  margin: 0 0 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.call {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-bottom: 12px;
  border-left: 4px solid #e4e4e7;
}

.call.ok { border-left-color: #0a7a35; }
.call.bad { border-left-color: #b91c1c; }

.status {
  display: inline-block;
  min-width: 40px;
  text-align: center;
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 13px;
  font-weight: 700;
  color: #ffffff;
  background-color: #71717a;
}

.s-2xx { background-color: #0a7a35; }
.s-4xx { background-color: #b45309; }
.s-5xx { background-color: #b91c1c; }
.s-err { background-color: #b91c1c; }

pre {
  background-color: #f4f4f5;
  border-radius: 8px;
  padding: 10px 12px;
  margin: 0 0 8px;
  overflow-x: auto;
  font-size: 13px;
  white-space: pre-wrap;
}

pre:last-child { margin-bottom: 0; }

// Deploy job нь ЗӨВХӨН main салбар дээр, CI амжилттай үед ажиллана.
// context: { branch, ci } — ci нь "success" эсвэл "failure".
// main + success бол л true буцаа.

function shouldDeploy(context) {
  // энд бичнэ үү
}

// «Deploy турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

window.DEPLOY_MAIN = null;
window.DEPLOY_PR = null;
window.DEPLOY_FAIL = null;

try {
  window.DEPLOY_MAIN = shouldDeploy({ branch: "main", ci: "success" });
  window.DEPLOY_PR = shouldDeploy({ branch: "feature/search", ci: "success" });
  window.DEPLOY_FAIL = shouldDeploy({ branch: "main", ci: "failure" });
  panel(window.DEPLOY_MAIN ? "ok" : "bad", "main", "main + ногоон CI", ["shouldDeploy → " + String(window.DEPLOY_MAIN)]);
  panel(!window.DEPLOY_PR ? "ok" : "bad", "pr", "feature салбар", ["shouldDeploy → " + String(window.DEPLOY_PR)]);
  panel(!window.DEPLOY_FAIL ? "ok" : "bad", "fail", "main + унасан CI", ["shouldDeploy → " + String(window.DEPLOY_FAIL)]);
} catch (problem) {
  panel("bad", "error", "Алдаа", [problem.message]);
}

document.body.dataset.ready = "1";

// Deploy нь зөвхөн main дээр, CI ногоон үед л ажиллана.

function shouldDeploy(context) {
  return context.branch === "main" && context.ci === "success";
}
